tasks.check:
set -eo pipefail
mkdir -p /home/bcorfman/dev/ringer-work/storylet-followups/out
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
git add -A
git diff --cached > /home/bcorfman/dev/ringer-work/storylet-followups/out/storylet-followups.patch
changed=$(git diff --cached --name-only)
[ -n "$changed" ] || { echo "no changes made"; exit 1; }
for f in $changed; do
  case " storygame/runtime/engine.py storygame/runtime/state.py storygame/runtime/validation.py storygame/runtime/reveal_eligibility.py storygame/runtime/canonical_events.py storygame/story_package/models.py storygame/story_package/loader.py tests/test_storylet_followups.py tests/test_recent_cue_unit.py tests/test_1a_drawer_close_gap.py tests/test_recent_cue_reference.py " in *" $f "*) ;; *) echo "edited a file outside this task: $f"; exit 1;; esac
done
echo "$changed" | grep -q "^storygame/" || { echo "no engine change"; exit 1; }
[ -f tests/test_storylet_followups.py ] || { echo "missing tests/test_storylet_followups.py"; exit 1; }
if git diff --cached -U0 | grep -E '^\+' | grep -nE 'pytest\.(skip|xfail)|mark\.(skip|xfail)|except Exception: *pass|fired_event_ids\.(discard|remove)'; then echo "added a skip, xfail, swallowed exception or a hand un-fire of a storylet"; exit 1; fi
if grep -nE 'fired_event_ids\.(discard|remove)\("SL-1A' tests/test_recent_cue_unit.py tests/test_1a_drawer_close_gap.py tests/test_recent_cue_reference.py tests/test_storylet_followups.py; then echo "a hand re-arm of an SL-1A storylet remains in the tests"; exit 1; fi
if grep -nE 'k_sl_1a_|SL-1A|drawer' $(git diff --cached --name-only -- storygame/) ; then echo "engine code names story ids; the rule must be story-agnostic"; exit 1; fi
grep -q "k_sl_1a_f_r3" tests/test_storylet_followups.py || { echo "no real-story drawer regression test"; exit 1; }
py=$(git diff --cached --name-only --diff-filter=AM | grep -E '\.py$' || true)
[ -z "$py" ] || { .venv/bin/ruff format --check $py && .venv/bin/ruff check $py; }
s0=$SECONDS
PYTHONPATH=$PWD:$PWD/packages/worldkeeper/src TMPDIR=/tmp .venv/bin/python -m pytest -q -p no:cacheprovider -n 0 tests/test_storylet_followups.py > /tmp/sf-new.out 2>&1 || { tail -25 /tmp/sf-new.out; echo "new tests fail"; exit 1; }
tail -2 /tmp/sf-new.out
grep -qE "([3-9]|[1-9][0-9]+) passed" /tmp/sf-new.out || { echo "fewer than 3 new tests ran"; exit 1; }
e0=$((SECONDS-s0)); echo "new tests alone: $e0 s (budget 20 s)"
[ "$e0" -le 20 ] || { echo "new tests over the 20 s budget"; exit 1; }
! grep -q "mark.nightly" tests/test_storylet_followups.py || { echo "new tests must be in the default suite"; exit 1; }
rc=0
PYTHONPATH=$PWD:$PWD/packages/worldkeeper/src TMPDIR=/tmp .venv/bin/python -m pytest -q -p no:cacheprovider -n 16 --run-nightly -rf tests/test_recent_cue_unit.py tests/test_cue_escalation.py tests/test_1a_drawer_close_gap.py tests/test_1a_gap_pointer.py tests/test_drawer_avoidance_repro.py tests/test_recent_cue_reference.py > /tmp/sf-cue.out 2>&1 || rc=$?
tail -6 /tmp/sf-cue.out
[ "$rc" = 0 ] || { echo "drawer and cue tests fail"; exit 1; }
s1=$SECONDS
rc=0
PYTHONPATH=$PWD:$PWD/packages/worldkeeper/src TMPDIR=/tmp .venv/bin/python -m pytest -q -p no:cacheprovider -n 16 -rf tests > /tmp/sf-full.out 2>&1 || rc=$?
tail -15 /tmp/sf-full.out
[ "$rc" = 0 ] || { echo "default suite fails (exit $rc)"; exit 1; }
e1=$((SECONDS-s1)); echo "default suite: $e1 s"
[ "$e1" -le 600 ] || { echo "default suite slower than 600 s"; exit 1; }
echo "PASS storylet-followups"
